def apply():
  f = base.ROOT / 'index.html'; s = f.read_text(); miss = []
  for a, b in R:
    c = s.count(a)
    if c != 1: miss.append((c, a[:80])); continue
    s = s.replace(a, b)
  f.write_text(s)
  base.P = P; base.main()
  print('missing replacements:', miss)

if __name__ == '__main__':
  apply()
